8	/// Reasoning parser for MiniMax M3 style outputs.
9	///
10	/// MiniMax M3 uses `<mm:think>...</mm:think>` delimiters. Its chat template may
11	/// prefill either delimiter depending on the requested thinking mode, so the
12	/// shared delimited parser derives the starting state from the rendered prompt.
13	pub struct MiniMaxM3ReasoningParser {
14	    inner: DelimitedReasoningParser,
15	    /// True until the first response text is classified. Only this position may
16	    /// drop a stray `</mm:think>` emitted at the start of a response.
17	    at_response_start: bool,
18	    /// Holds an initial suffix like `</mm` while it may still complete into the
19	    /// leading closer on a later chunk.
20	    leading_end_buffer: String,
21	}
