23	impl MiniMaxM3ReasoningParser {
24	    /// Create a MiniMax M3 parser backed by the shared delimited state machine.
25	    pub fn new(tokenizer: DynTokenizer) -> Result<Self> {
26	        Ok(Self {
27	            inner: DelimitedReasoningParser::new(tokenizer, M3_THINK_START, M3_THINK_END, false)?,
28	            at_response_start: true,
29	            leading_end_buffer: String::new(),
30	        })
31	    }
