33	    /// Drop a response-leading `</mm:think>` while preserving later unmatched
34	    /// closers as ordinary content.
35	    fn push_inner(&mut self, delta: &str) -> ReasoningDelta {
36	        if self.at_response_start && !self.inner.in_reasoning() {
37	            self.leading_end_buffer.push_str(delta);
38	            let buffered = std::mem::take(&mut self.leading_end_buffer);
39	
40	            if buffered.is_empty() {
41	                return ReasoningDelta::default();
42	            }
43	            if let Some(rest) = buffered.strip_prefix(M3_THINK_END) {
44	                self.at_response_start = false;
45	                return self.inner.push(rest);
46	            }
47	            if M3_THINK_END.starts_with(buffered.as_str()) {
48	                self.leading_end_buffer = buffered;
49	                return ReasoningDelta::default();
50	            }
51	
52	            self.at_response_start = false;
53	            return self.inner.push(&buffered);
54	        }
55	
56	        self.inner.push(delta)
57	    }
58	}
