60	fn append_delta(target: &mut ReasoningDelta, delta: ReasoningDelta) {
61	    if let Some(reasoning) = delta.reasoning {
62	        target.push_reasoning(&reasoning);
63	    }
64	    if let Some(content) = delta.content {
65	        target.push_content(&content);
66	    }
