91	            let pending = std::mem::take(&mut self.leading_end_buffer);
92	            self.at_response_start = false;
93	            append_delta(&mut delta, self.inner.push(&pending));
94	        }
95	        append_delta(&mut delta, self.inner.finish());
96	        Ok(delta)
97	    }
