5	/// Shared incremental state machine for tag-delimited reasoning protocols.
6	///
7	/// This helper is intentionally not a public parser type. Model-family parser
8	/// wrappers own one `DelimitedReasoningParser` internally and expose the
9	/// request-facing [`super::ReasoningParser`] trait.
10	///
11	/// The shared state machine stays generic by deriving its initial
12	/// `current_in_reasoning` state from the prompt token boundary instead of
13	/// hardcoding model-family conventions. That means families with the same
14	/// delimiters can often reuse this implementation even if their chat templates
15	/// prefill different prompts.
16	pub(crate) struct DelimitedReasoningParser {
17	    tokenizer: DynTokenizer,
18	    current_in_reasoning: bool,
19	    buffer: String,
20	    start_token: String,
21	    end_token: String,
22	    start_token_id: u32,
23	    end_token_id: u32,
24	    default_in_reasoning: bool,
25	}
26	
27	impl DelimitedReasoningParser {
28	    /// Create one delimited parser state machine.
29	    ///
30	    /// `default_in_reasoning` is only used when prompt initialization sees no
31	    /// reasoning boundary token at all. If the prompt contains either the
32	    /// start or end delimiter, that prompt boundary always wins.
33	    pub(crate) fn new(
34	        tokenizer: DynTokenizer,
35	        start_token: &'static str,
36	        end_token: &'static str,
37	        default_in_reasoning: bool,
38	    ) -> Result<Self> {
39	        let start_token_id =
40	            tokenizer.token_to_id(start_token).ok_or_else(|| ReasoningError::MissingToken {
41	                token: start_token.to_string(),
42	            })?;
43	        let end_token_id =
44	            tokenizer.token_to_id(end_token).ok_or_else(|| ReasoningError::MissingToken {
45	                token: end_token.to_string(),
46	            })?;
47	
48	        Ok(Self {
49	            tokenizer,
50	            current_in_reasoning: default_in_reasoning,
51	            buffer: String::new(),
52	            start_token: start_token.to_string(),
53	            end_token: end_token.to_string(),
54	            start_token_id,
55	            end_token_id,
56	            default_in_reasoning,
57	        })
58	    }
59	
60	    /// Initialize the starting state from prompt token IDs.
61	    pub(crate) fn initialize(&mut self, prompt_token_ids: &[u32]) {
62	        self.current_in_reasoning = last_reasoning_boundary(
63	            prompt_token_ids,
64	            self.start_token_id,
65	            self.end_token_id,
66	            self.tokenizer.as_ref(),
67	        )
68	        .unwrap_or(self.default_in_reasoning);
69	    }
70	
71	    /// Return whether the parser is currently inside a reasoning section.
72	    pub(crate) fn in_reasoning(&self) -> bool {
73	        self.current_in_reasoning
74	    }
75	
76	    /// Parse one decoded text delta and return its reasoning/content split.
77	    pub(crate) fn push(&mut self, delta: &str) -> ReasoningDelta {
78	        self.buffer.push_str(delta);
79	
80	        let partial_suffix_len = self.partial_suffix_len(&self.buffer);
81	        let stable_len = self.buffer.len() - partial_suffix_len;
82	        let pending_suffix = self.buffer.split_off(stable_len);
83	        let stable_text = std::mem::replace(&mut self.buffer, pending_suffix);
84	
85	        self.parse_stable_text(&stable_text)
86	    }
87	
88	    /// Flush any buffered partial delimiter suffix at end of stream.
89	    pub(crate) fn finish(&mut self) -> ReasoningDelta {
90	        let stable_text = std::mem::take(&mut self.buffer);
91	        self.parse_stable_text(&stable_text)
92	    }
93	
94	    /// Parse text that is known not to end with a partial delimiter suffix.
95	    fn parse_stable_text(&mut self, mut stable: &str) -> ReasoningDelta {
96	        let mut delta = ReasoningDelta::default();
97	
98	        while !stable.is_empty() {
99	            if self.current_in_reasoning {
100	                if let Some(end_idx) = stable.find(&self.end_token) {
101	                    delta.push_reasoning(&stable[..end_idx]);
102	                    stable = &stable[end_idx + self.end_token.len()..];
103	                    self.current_in_reasoning = false;
104	                } else {
105	                    delta.push_reasoning(stable);
106	                    break;
107	                }
108	            } else if let Some(start_idx) = stable.find(&self.start_token) {
109	                delta.push_content(&stable[..start_idx]);
110	                stable = &stable[start_idx + self.start_token.len()..];
111	                self.current_in_reasoning = true;
112	            } else {
113	                delta.push_content(stable);
114	                break;
115	            }
116	        }
117	
118	        delta
119	    }
120	
121	    /// Return the longest trailing suffix that could still complete a
122	    /// delimiter.
123	    fn partial_suffix_len(&self, text: &str) -> usize {
124	        let mut best = 0;
125	        for idx in text.char_indices().map(|(idx, _)| idx).skip(1) {
126	            let suffix = &text[idx..];
127	            if self.start_token.starts_with(suffix) && self.start_token != suffix {
128	                best = best.max(text.len() - idx);
129	            }
130	            if self.end_token.starts_with(suffix) && self.end_token != suffix {
131	                best = best.max(text.len() - idx);
132	            }
133	        }
134	
135	        if self.start_token.starts_with(text) && self.start_token != text {
136	            best = best.max(text.len());
137	        }
138	        if self.end_token.starts_with(text) && self.end_token != text {
139	            best = best.max(text.len());
140	        }
141	
142	        best
143	    }
144	}
