146	/// Determine the reasoning state implied by the last prompt boundary, if any.
147	fn last_reasoning_boundary(
148	    prompt_token_ids: &[u32],
149	    start_token_id: u32,
150	    end_token_id: u32,
151	    tokenizer: &dyn Tokenizer,
152	) -> Option<bool> {
153	    for token_id in prompt_token_ids.iter().rev() {
154	        if *token_id == start_token_id {
155	            return Some(true);
156	        }
157	        if *token_id == end_token_id {
158	            return Some(false);
159	        }
160	        if tokenizer.is_special_id(*token_id) {
161	            return None;
162	        }
163	    }
164	
165	    None
166	}
